    private void showSimplePreview(CartoonStage stage, boolean noBanner) {
        SimplePreviewFragment simplePreviewAdsFragment;
        this.mAutoExit = getIntent().getBooleanExtra(EXTRA_AUTOEXIT, false);
        Scene currentScene = SceneManager.getInstance().getCurrentScene();
        int intExtra = getIntent().getIntExtra(EXTRA_START, 0);
        int intExtra2 = getIntent().getIntExtra(EXTRA_END, currentScene.getFramesNumber() - 1);
        SimplePreviewPresenter simplePreviewPresenter = new SimplePreviewPresenter(stage, intExtra, intExtra2, new AbstractPreviewPresenter.IPlaybackCallback() { // from class: ru.jecklandin.stickman.features.preview.FullPreviewActivity.1
            final AudioPlaybackUseCase mPlayback;

            {
                this.mPlayback = new AudioPlaybackUseCase(FullPreviewActivity.this.mCartoonStage.audio());
            }

            @Override // ru.jecklandin.stickman.features.preview.AbstractPreviewPresenter.IPlaybackCallback
            public void onStopped() {
                this.mPlayback.stop();
            }

            @Override // ru.jecklandin.stickman.features.preview.AbstractPreviewPresenter.IPlaybackCallback
            public void onStarted(@Nonnull Scene movie, int startIndex) {
                this.mPlayback.startAt((long) (Math.max(0, startIndex) * 16.666666f));
            }
        });
        this.mSimplePreviewPresenter = simplePreviewPresenter;
        if (noBanner) {
            simplePreviewAdsFragment = SimplePreviewFragment.getInstance(simplePreviewPresenter);
        } else {
            simplePreviewAdsFragment = SimplePreviewAdsFragment.getInstance(simplePreviewPresenter);
        }
        this.mSimplePreviewFragment = simplePreviewAdsFragment;
        getSupportFragmentManager().beginTransaction().add(R.id.container, this.mSimplePreviewFragment).commit();
        setupBoneToggle();
        scheduleMotionGraphIfEnabled(currentScene, intExtra, intExtra2);
        this.mSimplePreviewPresenter.onGenerateRequested();
    }
